"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { ArrowLeft, Upload, ClipboardPaste, CheckCircle2, AlertCircle, AlertTriangle } from "lucide-react";
import { HandoffSchema } from "@/lib/handoff/validate";
import { db } from "@/lib/firebase/client";
import { getGuestId } from "@/lib/guest";
import { doc, setDoc } from "firebase/firestore";

export default function ImportPage() {
  const [jsonInput, setJsonInput] = useState("");
    const [status, setStatus] = useState<{ type: 'error' | 'success' | 'warn'; title: string; message: string } | null>(null);
      const [isImporting, setIsImporting] = useState(false);
        const router = useRouter();

          const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
              const file = e.target.files?.[0];
                  if (!file) return;
                      const reader = new FileReader();
                          reader.onload = (event) => {
                                setJsonInput(event.target?.result as string);
                                      setStatus({ type: 'success', title: 'File loaded', message: file.name });
                                          };
                                              reader.readAsText(file);
                                                };

                                                  const handleValidate = async () => {
                                                      if (!jsonInput.trim()) {
                                                            setStatus({ type: 'error', title: 'Empty input', message: 'Paste JSON or upload file' });
                                                                  return;
                                                                      }

                                                                          setIsImporting(true);
                                                                              setStatus(null);

                                                                                  try {
                                                                                        const parsed = JSON.parse(jsonInput);
                                                                                              const validation = HandoffSchema.safeParse(parsed);

                                                                                                    if (!validation.success) {
                                                                                                            const firstError = validation.error.errors[0];
                                                                                                                    setStatus({ 
                                                                                                                              type: 'error', 
                                                                                                                                        title: 'Validation Failed', 
                                                                                                                                                  message: firstError ? `${firstError.path.join('.')}: ${firstError.message}` : 'Invalid JSON structure'
                                                                                                                                                          });
                                                                                                                                                                  setIsImporting(false);
                                                                                                                                                                          return;
                                                                                                                                                                                }

                                                                                                                                                                                      // Expiry check
                                                                                                                                                                                            const expiryDate = new Date(validation.data.creatoros_handoff.expires_at).getTime();
                                                                                                                                                                                                  if (expiryDate < Date.now()) {
                                                                                                                                                                                                          setStatus({ type: 'error', title: 'Handoff Expired', message: 'This handoff is older than 30 days. Ask Grow to re-export.' });
                                                                                                                                                                                                                  setIsImporting(false);
                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                      setStatus({ 
                                                                                                                                                                                                                                              type: 'success', 
                                                                                                                                                                                                                                                      title: `Brand "${validation.data.brand.name}" found`, 
                                                                                                                                                                                                                                                              message: `Saving draft...` 
                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                // Generate unique ID
                                                                                                                                                                                                                                                                                      const draftId = crypto.randomUUID();
                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                  const draftData = {
                                                                                                                                                                                                                                                                                                          id: draftId,
                                                                                                                                                                                                                                                                                                                  brandName: validation.data.brand.name,
                                                                                                                                                                                                                                                                                                                          topic: validation.data.content.topic,
                                                                                                                                                                                                                                                                                                                                  createdBy: getGuestId(),
                                                                                                                                                                                                                                                                                                                                          createdAt: Date.now(),
                                                                                                                                                                                                                                                                                                                                                  status: "in_progress",
                                                                                                                                                                                                                                                                                                                                                          script: validation.data.content.script,
                                                                                                                                                                                                                                                                                                                                                                  seo: validation.data.seo,
                                                                                                                                                                                                                                                                                                                                                                          handoffId: validation.data.creatoros_handoff.handoff_id,
                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                      // Save to Firestore
                                                                                                                                                                                                                                                                                                                                                                                            await setDoc(doc(db, "drafts", draftId), draftData);
                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                        // Redirect to Studio
                                                                                                                                                                                                                                                                                                                                                                                                              router.push(`/studio?topic=${encodeURIComponent(validation.data.content.topic)}`);

                                                                                                                                                                                                                                                                                                                                                                                                                  } catch (err: unknown) {
                                                                                                                                                                                                                                                                                                                                                                                                                        console.error(err);
                                                                                                                                                                                                                                                                                                                                                                                                                               const message = err instanceof Error ? err.message : "";
                                                                                                                                                                                                                                                                                                                                                                                                                               if (message.includes("JSON")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                      setStatus({ type: 'error', title: 'JSON Invalid', message: 'Could not parse JSON. Check for syntax errors.' });
                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    setStatus({ type: 'error', title: 'Database Error', message: 'Failed to save draft. Check console for details.' });
                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                setIsImporting(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <main className="fixed inset-0 flex flex-col bg-[#0a0a0a] text-white">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <header className="flex-shrink-0 flex items-center justify-between px-5 py-4 border-b border-white/5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button onClick={() => router.back()} className="p-2 -ml-2 text-gray-400 hover:text-white transition">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <ArrowLeft size={20} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h1 className="text-sm font-bold">Import from Grow</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="w-8"></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </header>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="flex-1 overflow-y-auto p-5 flex flex-col">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="text-sm text-gray-400 mb-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Paste handoff JSON or upload <span className="text-[#4ECDC4] font-mono text-xs">.creatoros</span> file
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="flex-1 flex flex-col min-h-[200px] mb-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label className="block text-[10px] font-semibold text-gray-500 uppercase tracking-wider mb-2">Handoff JSON</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <textarea
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          value={jsonInput}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onChange={(e) => { setJsonInput(e.target.value); setStatus(null); }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  placeholder='{ "creatoros_handoff": { "version": "1.0" ... } }'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              className="flex-1 w-full p-4 bg-[#121212] border border-white/5 rounded-xl text-xs font-mono text-gray-300 placeholder-gray-600 focus:border-[#4ECDC4] focus:outline-none resize-none"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ></textarea>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="grid grid-cols-2 gap-3 mb-4 flex-shrink-0">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onClick={async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const text = await navigator.clipboard.readText();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setJsonInput(text);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setStatus({ type: 'success', title: 'Pasted', message: 'From clipboard' });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setStatus({ type: 'warn', title: 'Clipboard blocked', message: 'Please paste manually' });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                className="flex items-center justify-center gap-2 py-3 rounded-xl bg-[#121212] border border-white/5 text-sm font-medium text-gray-300 hover:bg-white/5 transition"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <ClipboardPaste size={16} /> Paste
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="relative">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <input type="file" accept=".creatoros,.json" onChange={handleFileUpload} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button className="w-full h-full flex items-center justify-center gap-2 py-3 rounded-xl bg-[#121212] border border-white/5 text-sm font-medium text-gray-300 hover:bg-white/5 transition">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Upload size={16} /> Upload
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {status && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className={`p-3.5 rounded-xl border flex items-start gap-3 flex-shrink-0 animate-in fade-in slide-in-from-bottom-2 ${
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      status.type === 'error' ? 'bg-red-500/10 border-red-500/30 text-red-400' :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  status.type === 'warn' ? 'bg-yellow-500/10 border-yellow-500/30 text-yellow-400' :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'bg-emerald-500/10 border-emerald-500/30 text-emerald-400'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {status.type === 'error' && <AlertCircle size={18} className="mt-0.5 flex-shrink-0" />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {status.type === 'warn' && <AlertTriangle size={18} className="mt-0.5 flex-shrink-0" />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {status.type === 'success' && <CheckCircle2 size={18} className="mt-0.5 flex-shrink-0" />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="text-sm font-bold">{status.title}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p className="text-xs opacity-80 mt-0.5">{status.message}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="p-5 border-t border-white/5 bg-[#0a0a0a]">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onClick={handleValidate}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          disabled={isImporting}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className="w-full py-3.5 rounded-xl bg-[#4ECDC4] text-[#0a0a0a] font-bold text-sm hover:bg-emerald-300 transition shadow-lg shadow-[#4ECDC4]/20 disabled:opacity-50 flex justify-center items-center h-[50px]"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {isImporting ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   <div className="w-5 h-5 border-2 border-[#0a0a0a] border-t-transparent rounded-full animate-spin"></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         "Validate & Import"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }